#[test]
fn save_path_canonicalizes_parent_and_rejects_missing_parent_and_dot_leaf() {
    let fixture = Fixture::new();
    let grant = fixture.mkdir("grant");
    let policy = fixture.policy(&grant);
    let new_path = grant.join("new.svg");
    assert_eq!(policy.resolve_save_path(text(&new_path)).unwrap(), fs::canonicalize(&grant).unwrap().join("new.svg"));
    assert_eq!(policy.resolve_save_path(&format!("{}/", new_path.display())), Err(AccessError::InvalidPath));
    assert_eq!(policy.resolve_save_path(text(&grant.join("missing/new.svg"))), Err(AccessError::NotFound));
    assert_eq!(policy.resolve_save_path(text(&grant)), Err(AccessError::NotRegularFile));
