#[test]
fn malformed_and_oversized_paths_are_denied() {
    let fixture = Fixture::new();
    let grant = fixture.mkdir("grant");
    let file = fixture.file("grant/a.svg");
    let policy = fixture.policy(&grant);
    let too_long = "x".repeat(PATH_CAP);

    assert_eq!(policy.resolve_existing(""), Err(AccessError::InvalidPath));
    assert_eq!(policy.resolve_existing("x\0y"), Err(AccessError::InvalidPath));
    assert_eq!(policy.resolve_existing(&too_long), Err(AccessError::InvalidPath));
    assert!(!policy.path_allowed(&too_long));
    assert_eq!(policy.resolve_existing(text(&grant)), Err(AccessError::NotRegularFile));
    assert_eq!(policy.resolve_existing(text(&fixture.path("absent.svg"))), Err(AccessError::NotFound));
