257	                Ok(0) => {
258	                    complete = true;
259	                    break;
260	                }
261	                Ok(_) => {
262	                    line[length] = byte[0];
263	                    length += 1;
264	                    if byte[0] == b'\n' {
265	                        complete = true;
266	                        break;
267	                    }
268	                }
269	                Err(_) => return false,
270	            }
271	        }
272	        if length == 0 {
273	            break;
274	        }
275	        lines += 1;
276	        if length == CONFIG_LINE_CAP && !complete {
277	            continue;
278	        }
279	        let line_bytes = &line[..length];
280	        let nul = line_bytes.iter().position(|byte| *byte == 0).unwrap_or(length);
281	        let mut end = nul;
282	        while end > 0 && is_ascii_space(line[end - 1]) {
283	            end -= 1;
284	        }
285	        let mut start = 0;
286	        while start < end && is_ascii_space(line[start]) {
287	            start += 1;
288	        }
289	        if start == end || line[start] == b'#' {
290	            continue;
291	        }
292	        let candidate = PathBuf::from(OsString::from_vec(line[start..end].to_vec()));
293	        if canonical_directory(&candidate).is_ok_and(|directory| path_is_inside(&directory, path)) {
294	            return true;
295	        }
296	    }
297	    false
298	}
